            br, bc = r, c
            while br > 0 and c - bc >= 0 and grid[br-1][c] == 7:
                br -= 1
            while bc > 0 and r - br >= 0 and grid[br][bc-1] == 7:
                bc -= 1

            er, ec = br, bc
            while er < 14 and ec < 21 and grid[er+1][ec] == 7:
                er += 1
            while ec < 21 and er - br >= 0 and grid[br][ec+1] == 7:
                ec += 1

            # Check if it's a solid block
            solid = True
            for i in range(br, er+1):
